with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('øve sig', 'phrase', '56823878-836c-5eb9-a444-4c4f4b1083f5', 1, 'verb', null, 'to practise', 'Hun øver sig på klaver hver dag.', 'She practices the piano every day.'), ('læne sig', 'phrase', '013833bb-1425-5b87-9053-c7653b8f39bf', 1, 'verb', null, 'to lean', 'Hun læner sig mod væggen, mens hun taler i telefon.', 'She leans against the wall while talking on the phone.'), ('holde på', 'phrase', '0707e9eb-08bf-5873-832b-0e7d35f3c944', 1, 'verb', null, 'to insist (on something)', 'Han holder på, at vi skal tage af sted nu.', 'He insists that we should leave now.'), ('falde fra', 'phrase', '046002ff-cac3-55d9-a214-5388eb28c90f', 1, 'verb', null, 'to drop out (of a group, course)', 'Mange elever falder fra i løbet af det første år.', 'Many students drop out during the first year.'), ('leve af', 'phrase', 'b616cf6f-7112-5f9b-a5c5-ebc2c80d856e', 1, 'verb', null, 'to live on (money)', 'De lever af en lille pension.', 'They live on a small pension.'), ('leve med', 'phrase', '923eb2a9-aff3-5609-9fb9-f927f681839d', 1, 'verb', null, 'to put up with (something)', 'Jeg lever med støjen fra vejen.', 'I put up with the noise from the road.'), ('udvikle sig', 'phrase', 'dc9dc530-6f24-5b8b-867e-9cae243dcb13', 1, 'verb', null, 'to develop', 'Byen har udviklet sig meget de sidste år.', 'The city has developed a lot in recent years.'), ('bryde sammen', 'phrase', '7a6fff2f-1d66-5456-9fbe-8d0953725475', 1, 'verb', null, 'to break down (emotionally)', 'Hun brød sammen, da hun hørte nyheden.', 'She broke down when she heard the news.'), ('om bord', 'phrase', '033732c3-83b3-5c6c-a288-3ef3fd8edfb2', 1, 'adverb', null, 'on board', 'Passagererne gik om bord på færgen.', 'The passengers boarded the ferry.'), ('bestemme sig for', 'phrase', 'e5bae13a-8df1-5262-a8bc-230ef02c3585', 1, 'verb', null, 'to decide on', 'Jeg har bestemt mig for at lære dansk.', 'I have decided to learn Danish.'), ('hvem som helst', 'phrase', '1aba39f7-b973-5e0d-be7c-9a77d537612d', 1, 'phrase', null, 'anyone', 'Du kan spørge hvem som helst om hjælp.', 'You can ask anyone for help.'), ('tillade sig', 'phrase', '472ac294-91a8-5450-9be9-fbe3736baf33', 1, 'verb', null, 'to allow oneself (something not usually permitted)', 'Hun tillod sig et lille stykke kage til kaffen.', 'She allowed herself a small piece of cake with the coffee.'), ('tillade sig', 'phrase', 'a413a4eb-2e37-567b-ac13-bf805ad5804b', 2, 'verb', null, 'to take the liberty (of doing something bold)', 'Han tillod sig at afbryde chefen under mødet.', 'He allowed himself to interrupt the boss during the meeting.'), ('sove over sig', 'phrase', '8233bd8e-d429-5bd6-b70f-c30088f08820', 1, 'verb', null, 'to oversleep', 'Jeg sov over mig i morges og kom for sent på arbejde.', 'I overslept this morning and was late for work.'), ('være afhængig af', 'phrase', '7b7428a0-cb73-5395-83f3-c97cec44f832', 1, 'verb', null, 'to depend on', 'Hun er afhængig af sin bil for at komme på arbejde.', 'She depends on her car to get to work.'), ('være afhængig af', 'phrase', '7d1599b5-b10c-56b4-8a64-d11e71bdefe6', 2, 'verb', null, 'to be addicted to', 'Min bror var afhængig af alkohol i mange år.', 'My brother was addicted to alcohol for many years.'), ('røre sig', 'phrase', '30c6735e-8957-5e57-9741-16af095ab49c', 1, 'verb', null, 'to move (oneself)', 'Jeg rører mig meget i løbet af dagen.', 'I move a lot during the day.'), ('røre ved', 'phrase', 'b8d36e35-a9f4-5e00-b0a1-fec562ec4987', 1, 'verb', null, 'to touch (physically)', 'Du må ikke røre ved den varme ovn.', 'Do not touch the hot oven.'), ('sige farvel til', 'phrase', '31ec7569-c257-51d7-a6f9-9bee4cbb98b9', 1, 'verb', null, 'to say goodbye to', 'Hun sagde farvel til sine venner i lufthavnen.', 'She said goodbye to her friends at the airport.'), ('komme af', 'phrase', '6e763cc2-7c4c-5f65-b253-d629789ea8df', 1, 'verb', null, 'to come from (be caused by)', 'Problemet kom af en misforståelse.', 'The problem came from a misunderstanding.'), ('komme op', 'phrase', '8a65a512-3bc0-5c22-b5fd-9f5e237e21d4', 1, 'verb', null, 'to get up (out of bed)', 'Jeg kommer op klokken syv hver morgen.', 'I get up at seven o''clock every morning.'), ('komme op', 'phrase', '742615c3-7839-5572-bb61-e991f6a43752', 2, 'verb', null, 'to come up (upstairs)', 'Børnene kommer op til os om aftenen.', 'The children come up to us in the evening.'), ('stå af', 'phrase', '2392379a-2352-528b-98b4-cc9ca924e260', 1, 'verb', null, 'to get off (a vehicle)', 'Jeg står af bussen ved stationen.', 'I get off the bus at the station.'), ('sætte sig ind i', 'phrase', '392f5275-92b1-5150-9c7b-c51d53ce62f4', 1, 'verb', null, 'to familiarise oneself with', 'Jeg sætter mig ind i de nye regler i aften.', 'I will familiarise myself with the new rules tonight.'), ('skrive af', 'phrase', 'cc7d95bb-fc0e-5188-8de8-b8d1dbcb92aa', 1, 'verb', null, 'to copy (by writing)', 'Eleverne skrev af fra tavlen i timen.', 'The students copied from the blackboard during the lesson.'), ('komme igen', 'phrase', 'dbc4334b-5b6b-593c-833e-3caa46522f93', 1, 'verb', null, 'to come back', 'Jeg kommer igen i morgen.', 'I''ll be back tomorrow.'), ('komme frem', 'phrase', 'aa7692a1-b892-55ea-b46f-0954dbbfb65f', 1, 'verb', null, 'to appear (become visible)', 'Solen kom frem bag skyerne.', 'The sun came out from behind the clouds.'), ('komme frem', 'phrase', 'b3a99685-3e4d-592c-b50a-35db4018a52f', 2, 'verb', null, 'to arrive (reach a place)', 'Vi kom frem til stationen efter en time.', 'We arrived at the station after an hour.'), ('sætte sig ned', 'phrase', '99a90562-f522-5f2e-b3c7-b1e20917976e', 1, 'verb', null, 'to sit down', 'Han sætter sig ned på stolen og læser en bog.', 'He sits down on the chair and reads a book.'), ('have fri', 'phrase', 'a3ed6c81-de3d-59dc-a43b-6cc0ac20d625', 1, 'verb', null, 'to have a day off', 'Jeg har fri i morgen, så vi kan tage på stranden.', 'I have the day off tomorrow so we can go to the beach.'), ('kigge ind', 'phrase', 'b3c1a1d3-c041-5a8c-be78-25b68fbd48d1', 1, 'verb', null, 'to drop by', 'Jeg kigger ind til dig i morgen.', 'I''ll drop by your place tomorrow.'), ('køre forbi', 'phrase', '4249ba67-8858-567b-b4b7-d52f49cad661', 1, 'verb', null, 'to drive past', 'Bussen kører forbi skolen hver morgen.', 'The bus drives past the school every morning.'), ('mangel på', 'phrase', '7031088c-2bd9-55cf-bcf0-c0eb97c9ad8b', 1, 'phrase', null, 'lack (of something)', 'Der er mangel på vand i byen.', 'There is a shortage of water in the city.'), ('forsvare sig', 'phrase', 'abec1d17-eb82-5f86-b47c-3de2dfc55127', 1, 'verb', null, 'to defend oneself', 'Han forsvarede sig mod kritikken.', 'He defended himself against the criticism.'), ('opholde sig', 'phrase', '58e520af-0604-5b1f-a63f-705291e310c6', 1, 'verb', null, 'to stay (somewhere)', 'Vi opholder os mest i stuen om aftenen.', 'We spend most of our time in the living room in the evenings.'), ('tjekke ind', 'phrase', '328e4ee9-b553-5e04-bb0c-1f681b697688', 1, 'verb', null, 'to check in (hotel, flight)', 'Vi tjekker ind på hotellet klokken to.', 'We check in at the hotel at two o''clock.'), ('blive forelsket i', 'phrase', '52e7d30f-0afc-5c02-ae78-9d1769f7e10e', 1, 'verb', null, 'to fall in love with', 'Hun blev forelsket i sin kollega.', 'She fell in love with her colleague.'), ('være ked af det', 'phrase', '47410e7b-2c5b-58cf-b086-a5c5448eb426', 1, 'verb', null, 'to be sorry (about something), to be sad', 'Jeg er ked af det, fordi min kat er syg.', 'I''m sad because my cat is sick.'), ('skelne mellem', 'phrase', '5cdb0995-0c01-5fce-8425-8b056af22305', 1, 'verb', null, 'to distinguish (between)', 'Jeg kan ikke skelne mellem de to farver.', 'I can''t distinguish between the two colors.'), ('snige sig', 'phrase', 'cadea705-583c-5829-94f6-ba02cd558145', 1, 'verb', null, 'to sneak, to creep stealthily', 'Han sniger sig ind i køkkenet om natten.', 'He sneaks into the kitchen at night.'), ('snige sig', 'phrase', '1967e2b0-6c75-5f16-a316-e64a9d06e0dc', 2, 'verb', null, 'to creep in (of error, feeling)', 'Der sneg sig en fejl ind i teksten.', 'A mistake crept into the text.'), ('gå af', 'phrase', '0b2810e9-1016-530d-8f2c-86526a1e2996', 1, 'verb', null, 'to resign (from a position)', 'Direktøren gik af efter skandalen.', 'The director resigned after the scandal.'), ('gå af', 'phrase', '96dd718c-0f88-54f2-aa29-a74e34ce6cce', 2, 'verb', null, 'to get off (a vehicle)', 'Vi gik af bussen ved torvet.', 'We got off the bus at the main square.'), ('gå af', 'phrase', '6e450959-966f-5205-b590-fd1290e1ddb0', 3, 'verb', null, 'to come off (a stain)', 'Pletten gik af med sæbe.', 'The stain came off with soap.'), ('gå i gang', 'phrase', '76406061-0372-58da-877e-90961d727daf', 1, 'verb', null, 'to get started (on a task)', 'Vi gik i gang med opvasken efter middagen.', 'We started washing up after dinner.'), ('være klar til', 'phrase', '8940c08f-370b-5a0b-a7f4-54fae8b16799', 1, 'verb', null, 'to be ready (for sth)', 'Jeg er klar til at tage af sted nu.', 'I''m ready to go now.'), ('lade sig fortælle', 'phrase', 'f0e67ba9-a67e-5891-9164-fc571e82ebbd', 1, 'verb', null, 'to hear (from someone)', 'Jeg har ladet mig fortælle, at butikken lukker tidligt i dag.', 'I have been told that the store closes early today.'), ('følge af', 'phrase', 'd3767e03-6097-5061-93f7-7778e264be5a', 1, 'verb', null, 'to follow from (be a consequence)', 'Det følger af reglerne, at du skal betale.', 'It follows from the rules that you must pay.'), ('gå rundt', 'phrase', 'aa7e9b6f-d179-59f3-98f7-c1c98f767f68', 1, 'verb', null, 'to go around (an obstacle)', 'De gik rundt om det store hul i vejen.', 'They walked around the big hole in the road.'), ('købe ind', 'phrase', '83d3bfad-2f3e-5b57-8fbb-0b24cc02a20a', 1, 'verb', null, 'to shop (for groceries)', 'Vi køber ind til hele ugen om søndagen.', 'We shop for the whole week on Sundays.'), ('føre sig', 'phrase', '8c23608c-d9e7-5088-a97e-8c0767c25723', 1, 'verb', null, 'to behave (in a certain way)', 'Han fører sig som en rigtig gentleman.', 'He behaves like a real gentleman.'), ('tage på i vægt', 'phrase', '3dde2b47-c4ce-57e1-aa38-5bd6a901bcb9', 1, 'verb', null, 'to gain weight', 'Jeg tager på i vægt, hvis jeg spiser for meget slik.', 'I gain weight if I eat too many sweets.'), ('få fat i', 'phrase', '90e64691-83ef-57b5-9531-041b0d72487e', 1, 'verb', null, 'get hold of (someone)', 'Jeg fik fat i lægen i går.', 'I got hold of the doctor yesterday.'), ('kendskab til', 'phrase', '105071a6-c50f-5334-abb4-5df2c597588b', 1, 'phrase', null, 'knowledge (of something)', 'Han har et godt kendskab til dansk historie.', 'He has a good knowledge of Danish history.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0004' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
